"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Upload } from "@/components/ui/icons";

// File Upload: generated by UIX from the design system. Same variants and sizes as the Figma component.

const fileUploadVariants = cva(
  "group/upload flex w-full cursor-pointer flex-col items-center text-center border-dashed transition-colors gap-3 p-6 bg-surface border border-line-default hover:border-line-strong data-[dragging]:bg-brand-subtle data-[dragging]:border-line-brand has-[:focus-visible]:ring-3 has-[:focus-visible]:ring-line-focus has-[:disabled]:cursor-not-allowed has-[:disabled]:text-fg-disabled data-[invalid]:border-line-danger rounded-lg",
);

export interface FileUploadProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "type" | "size" | "value" | "onChange" | "prefix">,
    VariantProps<typeof fileUploadVariants> {
  /** Called with the chosen or dropped files. */
  onFiles?: (files: File[]) => void;
  /** Text under the prompt, for example the accepted types. */
  helper?: React.ReactNode;
  /** Error message; replaces the helper text and turns the zone red. */
  error?: string;
}

const FileUpload = React.forwardRef<HTMLInputElement, FileUploadProps>(
  ({ className, onFiles, helper, error, disabled, ...props }, ref) => {
    const [dragging, setDragging] = React.useState(false);
    return (
      <label data-slot="file-upload" data-kind="surface"
        data-dragging={dragging ? "" : void 0}
        data-invalid={error ? "" : void 0}
        onDragOver={(event) => {
          event.preventDefault();
          if (!disabled) setDragging(true);
        }}
        onDragLeave={() => setDragging(false)}
        onDrop={(event) => {
          event.preventDefault();
          setDragging(false);
          if (!disabled) onFiles?.(Array.from(event.dataTransfer.files));
        }}
        className={cn(fileUploadVariants({  }), className)}
      >
        <input ref={ref} type="file" disabled={disabled} className="sr-only" {...props} onChange={(event) => onFiles?.(Array.from(event.target.files ?? []))} />
        <span aria-hidden className="inline-flex items-center justify-center rounded-full size-10 bg-subtle text-icon-secondary [&_svg]:size-5 group-data-[invalid]/upload:bg-danger-subtle group-data-[invalid]/upload:text-icon-danger">
          <Upload />
        </span>
        <span className="flex flex-wrap justify-center gap-1">
          <span className="text-label-medium text-fg-brand">Click to upload</span>
          <span className="text-body-small text-fg-secondary">or drag and drop</span>
        </span>
        {error || helper ? <span className={cn("text-body-xs text-fg-tertiary", error && "text-fg-danger")}>{error || helper}</span> : null}
      </label>
    );
  },
);
FileUpload.displayName = "FileUpload";

export { FileUpload, fileUploadVariants };
